//! Raw FFI bindings to the vendored ccv / nnc library.
//!
//! The bindings in `bindings.rs` are generated by bindgen from `wrapper.h`
//! (`cargo build -p nnc-sys --features regenerate-bindings`). Both supported
//! targets (aarch64-apple-darwin and x86_64/aarch64 Linux) are LP64, so the
//! same struct layouts apply; the layout tests in `bindings.rs` guard that.
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
#![allow(clippy::all)]

include!("bindings.rs");
